// The always-on warden (#1102) — now a REPORTER, not the enforcer.
//
// `the-warden-quarantines-from-rust-instead-of-the-render-loop`: the decision that hard-pauses a
// drifting worker, and the kill that carries it out, moved to `src-tauri/src/fleet/warden.rs`. That
// loop runs on the backend's own schedule, beside the PTY sessions it pauses. This hook now does the
// two things only the renderer can:
//   1. GATHER the trusted activity — the shared audit tail and the batched worktree diff — because
//      the store holds which panes are workers and where their worktrees are;
//   2. COMPUTE the conformance verdict, because `checkConformance`'s file-lane arm compiles a
//      stream's `owns` globs with the TypeScript matcher, and which glob engine is authoritative is
//      an open maintainer decision (`the-two-write-scope-glob-engines-disagree`). Recomputing it in
//      Rust would silently move a security boundary onto the other engine while that is pending.
// It then REPORTS. It no longer decides who is quarantined, and it never kills a PTY.
//
// Asymmetric by design — the watcher reads only structured, trusted telemetry (the plan, the git
// diff, the bsc-audit log), never the worker-ingested prose, so it can't itself be steered by an
// injection. Mount once at the app root so it runs on any screen.

import { useRef } from "react";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { bscJson } from "@/shared/lib/core/bsc";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { useLogStream } from "@/shared/hooks/useLogStream";
import { useAppStore } from "@/store";
import { roleCapability } from "@/shared/lib/session/sessionRoles";
import { resolveLlmConfig, hasLlmKey, type LlmConfig } from "@/shared/lib/core/llmConfig";
import { oneShotComplete } from "@/shared/lib/core/claudeComplete";
import type { WorktreeChanges } from "@/shared/lib/fleet/worktreeChanges";
import { checkConformance, type ConformanceVerdict } from "@/shared/lib/fleet/conformance";
import { parseAuditCommands, zipWorktreeChanges, wardenSweepTargets, livePaneIdsOf, type WardenSession } from "@/shared/lib/fleet/warden";
import { buildJudgePrompt, parseJudgeVerdict, selectForJudging } from "@/shared/lib/fleet/wardenJudge";
import { completedWorkerPanes, doneIssueRefs } from "@/shared/lib/fleet/streamCompletion";
import type { PlanIssue } from "@/features/planner/issues/planIssues";
import { log } from "@/shared/lib/core/log";

// #3643: event-driven — re-checks when a worker attempts a tool (`tool`/audit, the write signal the
// warden already reads), takes/finishes a turn (`activity`), or self-reports done, instead of
// re-spawning a git diff per worker every 6s.
const JUDGE_EVERY = 5;  // run the LLM spot-check ~every 5 ticks (~30s), one worker, round-robin

/** One pane's report: who it is, and what the deterministic check said about it. */
type ReportedPane = { paneId: string; streamId: string; verdict: ConformanceVerdict };

/** Gather one live worker's trusted activity + anchor, or null if it can't be evaluated.
 *
 *  #3908: PURE of I/O — the two reads it used to make per pane are hoisted to ONE per sweep by
 *  {@link sweepInputs} and passed in. Both were fan-out waste at fleet scale: `read_worktree_changes`
 *  spawns two git subprocesses (~78 per sweep at 39 panes, stalling the command queue ~11s), and the
 *  audit tail takes no pane argument at all — every worker was re-reading the SAME log, filtered
 *  per-pane only afterwards by `parseAuditCommands`. */
function buildSession(paneId: string, auditLines: string[], changesByPane: Map<string, string[]>): WardenSession | null {
  const st = useAppStore.getState();
  const stream = st.fleetPaneStreams[paneId];
  if (!stream) return null;
  const role = st.paneRoles[paneId] ?? "worker";
  if (role !== "worker") return null; // the warden watches workers — the exposed attack surface
  const cwd = st.paneCwds[paneId];
  if (!cwd) return null;

  const changedFiles = changesByPane.get(paneId) ?? [];
  return {
    paneId,
    anchor: {
      streamId: stream.id,
      ownedGlobs: stream.owns,
      capability: roleCapability(role, { writeGlobs: stream.owns }),
      flow: stream.flow,
    },
    activity: {
      changedFiles: changedFiles ?? [],
      // Ignore audit commands from before this pane's warden floor (set on triage relaunch) so a
      // prior run's denied command doesn't re-quarantine the freshly relaunched worker.
      commands: parseAuditCommands(auditLines ?? [], paneId, st.wardenSince[paneId] ?? 0),
    },
  };
}

/**
 * The reads a whole warden sweep shares, fetched ONCE (#3908) — the fix for the fan-out that stalled
 * the command queue ~11s at 39 panes.
 *
 * `logsTail("audit", …)` takes no pane argument, so one read serves every worker (`parseAuditCommands`
 * does the per-pane filtering). `read_worktree_changes_batch` replaces N git-spawning invokes with one,
 * index-aligned to the cwds we send. Targets mirror `buildSession`'s own guards so the batch never
 * pays for a pane that would be discarded anyway.
 */
async function sweepInputs(paneIds: string[]): Promise<{ auditLines: string[]; changesByPane: Map<string, string[]> }> {
  const st = useAppStore.getState();
  const targets = paneIds.filter((p) => {
    const stream = st.fleetPaneStreams[p];
    return !!stream && (st.paneRoles[p] ?? "worker") === "worker" && !!st.paneCwds[p];
  });
  const cwds = targets.map((p) => st.paneCwds[p] as string);
  const [auditLines, changes] = await Promise.all([
    logsTail("audit", 500),
    cwds.length ? safeInvoke<WorktreeChanges[]>("read_worktree_changes_batch", { cwds }, []) : Promise.resolve<WorktreeChanges[]>([]),
  ]);
  // Index-aligned zip (pure + unit-tested in warden.ts): a short/failed batch degrades each missing
  // pane to "no file signal", exactly as a failed single read did — never another worker's files.
  return { auditLines: auditLines ?? [], changesByPane: zipWorktreeChanges(targets, changes ?? []) };
}

/**
 * Hand the backend the fleet picture and every pane's verdict.
 *
 * A REPORT, not an instruction: `fleet::warden` decides who is quarantined and performs the kill, and
 * the report EXPIRES so a renderer that dies cannot leave a stale picture standing. This is the whole
 * flip — the renderer stopped being the thing that has to be alive for a hijacked worker to be caught.
 */
async function reportFleet(panes: ReportedPane[], completed: Iterable<string>): Promise<void> {
  const st = useAppStore.getState();
  await safeInvoke("warden_report_fleet", {
    report: {
      panes,
      tabs: st.tabs.map((t) => ({ paneIds: t.paneIds ?? [] })),
      ended: Object.keys(st.endedPanes),
      disabled: Object.keys(st.disabledPanes),
      completed: [...completed],
    },
  }, undefined, (e) => log.error(`warden: report failed: ${e}`));
}

/** Mirror the backend's quarantine record into the store, so the banner shows what Rust actually did.
 *  Rust OWNS the record now; this only renders it. */
async function syncQuarantines(streamOf: (paneId: string) => string): Promise<void> {
  const panes = await safeInvoke<string[]>("warden_quarantined_panes", {}, []);
  const st = useAppStore.getState();
  for (const paneId of panes ?? []) {
    if (!st.quarantinedPanes[paneId]) {
      st.markQuarantine(paneId, { streamId: streamOf(paneId), summary: "quarantined by the warden", at: Date.now() });
    }
  }
}

/** Escalate one worker to the LLM judge. A drift verdict is REPORTED like any other, so there is
 *  exactly ONE thing that kills a PTY. Fail-open: any error / unparseable reply leaves the worker
 *  running (the deterministic check is the gate). */
async function judgeAndMaybeReport(session: WardenSession, cfg: LlmConfig, completed: Iterable<string>): Promise<void> {
  const stream = useAppStore.getState().fleetPaneStreams[session.paneId];
  if (!stream) return;
  const { system, user } = buildJudgePrompt({
    streamId: session.anchor.streamId,
    ownedGlobs: session.anchor.ownedGlobs,
    issues: stream.issues,
    changedFiles: session.activity.changedFiles,
    commands: session.activity.commands,
  });
  const reply = await oneShotComplete(cfg, system, user).catch((e) => {
    log.error(`warden: judge call failed for ${session.paneId}: ${e}`);
    return "";
  });
  if (!reply) return;
  const verdict = parseJudgeVerdict(reply);
  if (verdict.drifted) {
    await reportFleet([{
      paneId: session.paneId,
      streamId: session.anchor.streamId,
      verdict: { onTask: false, trips: [{ kind: "denied-command", detail: `LLM judge: ${verdict.reason}` }] },
    }], completed);
  }
}

export function useWarden(): void {
  const tickCount = useRef(0);     // drives the judge cadence
  const judgeCursor = useRef(0);   // round-robin cursor for sampling
  const judging = useRef(false);   // one judge call in flight at a time

  useLogStream(["tool", "activity", "done"], async (isCancelled) => {
    if (isCancelled()) return;
    const st = useAppStore.getState();
    const panes = Object.keys(st.fleetPaneStreams);
    if (panes.length === 0) return;

    // A worker that finished every owned issue is in MAINTENANCE (#1957), not building — its
    // post-completion activity is expected, not drift. Read each project's issue statuses once per
    // tick (deduped by project key — a worker pane id is `<projectKey>:<streamId>`). The LIFT is the
    // backend's now; this only reports the set.
    const projectKeys = [...new Set(panes.map((p) => p.split(":")[0]).filter(Boolean))];
    const doneByProject = new Map<string, Set<string>>();
    await Promise.all(projectKeys.map(async (key) => {
      const issues = await bscJson<PlanIssue[]>(key, ["plan", "list", "--full", "--json"], []);
      doneByProject.set(key, doneIssueRefs(issues ?? []));
    }));
    if (isCancelled()) return;
    const completed = completedWorkerPanes(st.fleetPaneStreams, (paneId) => doneByProject.get(paneId.split(":")[0]));
    for (const paneId of completed) {
      if (st.quarantinedPanes[paneId]) st.clearQuarantine(paneId);
    }

    const fresh = useAppStore.getState();
    // #3954: gather activity only for panes with a RUNNING session. `panes` is the PLANNED roster —
    // after the resume rebuilt network-monitor's worktrees that was 47 panes against 3 live
    // terminals, and every pane costs two git subprocesses. The BACKEND bounds the sweep the same way
    // for its decision; this bound is what keeps the batch itself from fanning out.
    const liveIds = livePaneIdsOf(fresh.tabs, fresh.endedPanes, fresh.disabledPanes);
    const live = wardenSweepTargets(panes, liveIds, completed);
    // #3908: TWO invokes per sweep, not two per pane.
    const { auditLines, changesByPane } = await sweepInputs(live);
    if (isCancelled()) return;
    const sessions = live
      .map((p) => buildSession(p, auditLines, changesByPane))
      .filter((s): s is WardenSession => s !== null);

    // Layer 1 — compute the verdict and REPORT. The decision and the kill are the backend's.
    await reportFleet(
      sessions.map((s) => ({
        paneId: s.paneId,
        streamId: s.anchor.streamId,
        verdict: checkConformance(s.anchor, s.activity),
      })),
      completed,
    );
    if (isCancelled()) return;
    await syncQuarantines((paneId) => useAppStore.getState().fleetPaneStreams[paneId]?.id ?? "");

    // Layer 2 — LLM-judge spot-check (sampled, gated on an API key, one call at a time).
    tickCount.current += 1;
    if (tickCount.current % JUDGE_EVERY === 0 && !judging.current) {
      const cfg = resolveLlmConfig(st);
      if (hasLlmKey(cfg)) {
        const skip = new Set(Object.keys(useAppStore.getState().quarantinedPanes));
        const pick = selectForJudging(sessions.map((s) => s.paneId), judgeCursor.current++, skip);
        const session = pick ? sessions.find((s) => s.paneId === pick) : undefined;
        if (session) {
          judging.current = true;
          void judgeAndMaybeReport(session, cfg, completed).finally(() => { judging.current = false; });
        }
      }
    }
  }, []);
}
